#!/usr/bin/env python3
"""Generate portable runtime ABI data from the production contract registry."""

from __future__ import annotations

import argparse
from pathlib import Path

from py2rust.compiler.library_contracts import (
    LIBRARY,
    RUNTIME_PARAMETERS,
    RUNTIME_VALUE_READERS,
)

ROOT = Path(__file__).resolve().parents[1]
DESTINATION = ROOT / "py2rust/compiler/native/runtime_contracts.py"


def render_source() -> str:
    lines = [
        '"""Generated by tools/generate_native_contracts.py; edit library_contracts.py instead."""',
        "",
        "from dataclasses import dataclass",
        "",
        "",
        "@dataclass",
        "class RuntimeContract:",
        "    name: str",
        "    result: str",
        "    parameters: list[str]",
        "    shared: list[bool]",
        "    fallible: bool",
        "    value_reader: bool",
        "",
        "",
        "def runtime_contract(name: str) -> RuntimeContract:",
        '    missing: RuntimeContract = RuntimeContract("", "", [], [], False, False)',
    ]
    for name, (result, parameters, fallible) in sorted(LIBRARY.items()):
        shared = [parameter.passing == "shared" for parameter in RUNTIME_PARAMETERS[name]]
        lines += [
            f"    if name == {name!r}:",
            "        return RuntimeContract(",
            f"            {name!r},",
            f"            {result!r},",
            "            [",
        ]
        lines += [f"                {parameter!r}," for parameter in parameters]
        lines += [
            "            ],",
            f"            {shared!r},",
            f"            {fallible!r},",
            f"            {name in RUNTIME_VALUE_READERS!r},",
            "        )",
        ]
    lines += [
        '    assert False, "unregistered native runtime call: " + name',
        "    return missing",
        "",
    ]
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    source = render_source()
    if args.check:
        return 0 if DESTINATION.read_text() == source else 1
    DESTINATION.write_text(source)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
